static __inline__ UniversalProcPtr* GetTrapVector(uint16_t trapNumber) {
    if (trapNumber & 0x0800)
        return (UniversalProcPtr *)(0xE00 + ((trapNumber & 0x3FF) << 2));
    return (UniversalProcPtr *)(0x400 + ((trapNumber & 0xFF) << 2));
}

